package cn.shanhai.game;
public class PolishTest {
 static int n=0;static void ok(boolean b,String s){n++;if(!b)throw new AssertionError(s);}
 static boolean has(Board b,String id){b.render(InteractionTest.ink);for(Board.Hit h:b.hits)if(h.id.equals(id))return true;return false;}
 public static void main(String[]args){Board b=new Board(InteractionTest.host);b.game=RulesTest.blank();b.screen="battle";Engine e=b.game;RulesTest.give(e,0,0);RulesTest.give(e,0,11);ok(!has(b,"play"),"confirm disabled with no selection");b.action("card0");ok(!has(b,"play"),"attack requires target");ok(b.targetValid(1)&&!b.targetValid(2),"enemy attack target highlights");b.action("target1");ok(has(b,"play"),"valid target enables confirm");b.action("card0");ok(b.selected==-1&&b.target==-1,"same card cancels and clears target");b.action("card1");ok(b.targetValid(2)&&!b.targetValid(1),"support highlights ally only");b.action("target2");b.action("card0");ok(b.target==-1&&!has(b,"play"),"changing cards clears stale target");
 b.render(InteractionTest.ink);int count=e.totalCards();for(Board.Hit h:b.hits)if(h.id.equals("card0")){b.longPress(h.x+40,h.y+40);break;}ok(b.modal.equals("detail0")&&e.totalCards()==count,"long press inspects without playing");b.action("close");b.action("end");ok(b.modal.equals("confirmEnd")&&e.turn==0,"end confirmation preserves action phase");b.action("close");b.action("skill");ok(b.skillTarget,"target skill enters selection");b.action("skill");ok(!b.skillTarget,"target skill cancellation");
 b.action("settings");for(int i=0;i<15;i++)b.action("musicminus");ok(b.musicVol==0&&!b.music,"music lower bound and mute");for(int i=0;i<15;i++)b.action("musicplus");ok(b.musicVol==8&&b.music,"music upper bound");b.action("close");e.beats.clear();e.beat("card",0,1,0,0,"a");e.beat("hit",0,1,-1,1,"b");ok(b.tick()&&b.beat.text.equals("a"),"event queue first beat");b.beatAt=0;ok(b.tick()&&b.beat.text.equals("b"),"event queue second beat");b.modal="cards";b.action("cardpage");b.render(InteractionTest.ink);ok(b.modalPage==1,"dialog pagination independent of hand page");for(Board.Hit h:b.hits)if(h.id.equals("cardpage")){b.longPress(h.x+20,h.y+20);break;}ok(b.modal.equals("cards"),"long press pagination is not a card index");System.out.println("PASS "+n+" interaction-state regression assertions");}
}
